58			// Listen for settings changes to refresh agents
59			// Note: When settings change, we fire onDidChangeCustomAgents which causes VS Code to re-fetch
60			// the agent definition. However, handoff buttons already rendered may not work as
61			// these capture the model at render time.
62			this._register(this.configurationService.onDidChangeConfiguration(e => {
63				if (e.affectsConfiguration(ConfigKey.PlanAgentAdditionalTools.fullyQualifiedId) ||
64					e.affectsConfiguration(ConfigKey.Deprecated.PlanAgentModel.fullyQualifiedId) ||
65					e.affectsConfiguration('chat.planAgent.defaultModel') ||
66					e.affectsConfiguration(ConfigKey.ImplementAgentModel.fullyQualifiedId) ||
67					e.affectsConfiguration(ConfigKey.ExploreAgentEnabled.fullyQualifiedId) ||
68					e.affectsConfiguration(ConfigKey.Advanced.SearchSubagentToolEnabled.fullyQualifiedId)) {
