9	/**
10	 * A type representing a stateful marker that can be stored in an opaque part in raw chat messages.
11	 */
12	interface IStatefulMarkerContainer {
13		type: typeof CustomDataPartMimeTypes.StatefulMarker;
14		value: StatefulMarkerWithModel;
15	}
16	
17	type StatefulMarkerWithModel = { modelId: string; marker: string };
18	
19	export interface IStatefulMarkerContainerProps extends BasePromptElementProps {
20		statefulMarker: StatefulMarkerWithModel;
21	}
22	
23	/**
24	 * Helper to store the statefulMarker as part of a prompt-tsx assistant message
25	 */
26	export class StatefulMarkerContainer extends PromptElement<IStatefulMarkerContainerProps> {
27		render() {
28			const { statefulMarker } = this.props;
29			const container = { type: CustomDataPartMimeTypes.StatefulMarker, value: statefulMarker };
30			return <opaque value={container} />;
31		}
32	}
33	
34	/**
35	 * Check whether an opaque content part is a StatefulMarkerContainer and retrieve the stateful marker if so
36	 */
37	export function rawPartAsStatefulMarker(part: Raw.ChatCompletionContentPartOpaque): StatefulMarkerWithModel | undefined {
38		const value = part.value;
39		if (!value || typeof value !== 'object') {
40			return;
41		}
42	
43		const data = value as IStatefulMarkerContainer;
44		if (data.type === CustomDataPartMimeTypes.StatefulMarker && typeof data.value === 'object') {
45			return data.value;
46		}
47		return;
48	}
49	
50	export function encodeStatefulMarker(modelId: string, marker: string): Uint8Array {
51		return new TextEncoder().encode(modelId + '\\' + marker);
52	}
53	
54	export function decodeStatefulMarker(data: Uint8Array): StatefulMarkerWithModel {
55		const decoded = new TextDecoder().decode(data);
56		const [modelId, marker] = decoded.split('\\');
57		return { modelId, marker };
58	}
59	
60	/** Gets stateful markers from the messages, from the most to least recent */
61	export function* getAllStatefulMarkersAndIndicies(messages: readonly Raw.ChatMessage[]) {
62		for (let idx = messages.length - 1; idx >= 0; idx--) {
63			const message = messages[idx];
64			if (message.role === Raw.ChatRole.Assistant) {
65				for (const part of message.content) {
66					if (part.type === Raw.ChatCompletionContentPartKind.Opaque) {
67						const statefulMarker = rawPartAsStatefulMarker(part);
68						if (statefulMarker) {
69							yield { statefulMarker: statefulMarker, index: idx };
70						}
71					}
72				}
73			}
74		}
75		return undefined;
76	}
77	
78	export function getStatefulMarkerAndIndex(modelId: string, messages: readonly Raw.ChatMessage[]): { statefulMarker: string; index: number } | undefined {
79		for (const marker of getAllStatefulMarkersAndIndicies(messages)) {
80			if (marker.statefulMarker.modelId === modelId) {
81				return { statefulMarker: marker.statefulMarker.marker, index: marker.index };
82			}
83		}
84		return undefined;
85	}
86	
87	/**
88	 * Finds the message index of a specific stateful marker value in the message history.
89	 * Returns the index if found, undefined otherwise.
90	 */
91	export function getIndexOfStatefulMarker(markerValue: string, messages: readonly Raw.ChatMessage[]): number | undefined {
92		for (const entry of getAllStatefulMarkersAndIndicies(messages)) {
93			if (entry.statefulMarker.marker === markerValue) {
94				return entry.index;
95			}
96		}
97		return undefined;
98	}
